findings.codeql_raw_query:
/**
 * @name SQL injection in Django ORM/raw queries
 * @description Detects flows from remote/user-controlled sources into raw SQL execution helpers in Django.
 * @kind path-problem
 * @problem.severity error
 * @id py/django-sql-injection
 * @tags security
 *       framework
 *       external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module DjangoSQLConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // cursor.execute / cursor.executemany
      call = API::moduleImport("django.db").getMember("connection").getMember(["cursor"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module DjangoSQLFlow = TaintTracking::Global<DjangoSQLConfig>;
import DjangoSQLFlow::PathGraph

from DjangoSQLFlow::PathNode source, DjangoSQLFlow::PathNode sink
where DjangoSQLFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches raw SQL execution $@.", source.getNode(), "user input"

/**
 * @name Path traversal in Django file handling
 * @description Detects flows from remote/user-controlled sources into filesystem path operations in Django.
 * @kind path-problem
 * @problem.severity error
 * @id py/django-path-traversal
 * @tags security
 *       framework
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module DjangoPathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module DjangoPathTraversalFlow = TaintTracking::Global<DjangoPathTraversalConfig>;
import DjangoPathTraversalFlow::PathGraph

from DjangoPathTraversalFlow::PathNode source, DjangoPathTraversalFlow::PathNode sink
where DjangoPathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches filesystem path operation $@.", source.getNode(), "user input"
